"""Índice de correspondência exata do catálogo pet fornecido pelo usuário.

Somente códigos de referência e nomes têm fingerprints; IDs de produto/SKU
do e-commerce não são códigos da API FarmaLíder. Ausência no índice não
comprova uso humano. O arquivo original e seus demais dados ficam privados.
"""

from __future__ import annotations

import hashlib
import re
import unicodedata
from functools import lru_cache
from typing import Any


@lru_cache(maxsize=32768)
def catalog_fingerprint(kind: str, value: str) -> str:
    text = unicodedata.normalize("NFKD", value.casefold())
    text = "".join(char for char in text if not unicodedata.combining(char))
    if kind == "name":
        text = " ".join(re.findall(r"[a-z0-9]+", text))
    else:
        text = text.strip()
        if not text.isascii() or not text.isdigit():
            return ""
    if not text:
        return ""
    return hashlib.sha256(f"{kind}:{text}".encode()).hexdigest()


def catalog_contains(item: dict[str, Any]) -> bool:
    code = str(
        item.get("produto_codigo") or item.get("codigo") or item.get("codProduto") or ""
    )
    if catalog_fingerprint("reference", code) in _REFERENCE_FINGERPRINTS:
        return True
    name = str(item.get("produto_nome") or item.get("nome") or "")
    return catalog_fingerprint("name", name) in _NAME_FINGERPRINTS


